import React, { useEffect, useState } from "react";

function Facilities() {
  const [facilities, setFacilities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:8081/facilities")
      .then((res) => res.json())
      .then((data) => {
        setFacilities(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching facilities:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        <h1 style={styles.title}>Facilities</h1>

        {loading ? (
          <p>Loading facilities...</p>
        ) : facilities.length === 0 ? (
          <p>No facilities found.</p>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Name</th>
                  <th style={styles.th}>Address</th>
                  <th style={styles.th}>City</th>
                  <th style={styles.th}>State</th>
                  <th style={styles.th}>Zip Code</th>
                  <th style={styles.th}>Slots</th>
                  <th style={styles.th}>Contact</th>
                </tr>
              </thead>
              <tbody>
                {facilities.map((facility) => (
                  <tr
                    key={facility.facilityId}
                    style={styles.tr}
                    onMouseOver={(e) => (e.currentTarget.style.background = "#f0f8ff")}
                    onMouseOut={(e) => (e.currentTarget.style.background = "transparent")}
                  >
                    <td style={styles.td}>{facility.facilityName}</td>
                    <td style={styles.td}>{facility.address}</td>
                    <td style={styles.td}>{facility.city}</td>
                    <td style={styles.td}>{facility.state}</td>
                    <td style={styles.td}>{facility.zipCode}</td>
                    <td style={styles.td}>{facility.totalSlots}</td>
                    <td style={styles.td}>{facility.contactInfo || "-"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  page: {
    backgroundColor: "#f4f8fb",
    minHeight: "100vh",
    padding: "40px 20px",
    display: "flex",
    justifyContent: "center",
  },
  container: {
    backgroundColor: "#ffffff",
    padding: "30px",
    borderRadius: "12px",
    boxShadow: "0px 4px 15px rgba(0,0,0,0.1)",
    width: "100%",
    maxWidth: "1100px",
  },
  title: {
    fontSize: "2rem",
    color: "#0077b6",
    marginBottom: "20px",
    textAlign: "center",
    fontWeight: "bold",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
    fontSize: "0.95rem",
  },
  th: {
    backgroundColor: "#0077b6",
    color: "#ffffff",
    padding: "12px",
    textAlign: "left",
    borderBottom: "2px solid #ddd",
  },
  td: {
    padding: "12px",
    borderBottom: "1px solid #e0e0e0",
    color: "#333",
  },
  tr: {
    transition: "background-color 0.2s ease",
  },
};

export default Facilities;
